# Generated by scripts/homebrew_formula.sh in bircni/cargo-wash on every release.
# Changes made here are overwritten by the next release.
class CargoWash < Formula
  desc "Clean up the target folders of all your Cargo projects"
  homepage "https://github.com/bircni/cargo-wash"
  license "MIT"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/bircni/cargo-wash/releases/download/2.0.0/cargo-wash-2.0.0-aarch64-apple-darwin.tar.gz"
      sha256 "5a366f9e40a970146b9d942c6aa1f965b8689c0e9638dfb93673507ef3d473ef"
    end
    on_intel do
      url "https://github.com/bircni/cargo-wash/releases/download/2.0.0/cargo-wash-2.0.0-x86_64-apple-darwin.tar.gz"
      sha256 "c43f0ac06d10df1d8e5354ee695ae739018d54386a6ca3e6a517083ecebe8703"
    end
  end

  on_linux do
    # Only an x86_64 build is published for Linux.
    depends_on arch: :x86_64

    on_intel do
      url "https://github.com/bircni/cargo-wash/releases/download/2.0.0/cargo-wash-2.0.0-x86_64-unknown-linux-musl.tar.gz"
      sha256 "641f0983f61d45b41e4b41d5f0a4a5a9c476471de60e4c5cd896bea63918948b"
    end
  end

  def install
    bin.install "cargo-wash"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/cargo-wash --version")

    (testpath/"scan").mkpath
    output = shell_output("#{bin}/cargo-wash stats --json --path #{testpath}/scan")
    assert_equal({ "projects" => [], "total_size" => 0 }, JSON.parse(output))
  end
end
